        {
            ["App:Name"]        = "HttpMcpServer",
            ["App:Version"]     = "1.0.0",
            ["App:Environment"] = "Development",
            ["Logging:Level"]   = "Information",
            ["Logging:Format"]  = "json",
            ["Feature:DarkMode"] = "true",
            ["Feature:BetaApi"]  = "false",
        };
}

